(** 0RB0LC_1RC0RD_1LA0LB_1LC1RB *)
Definition tm_0RB0LC_1RC0RD_1LA0LB_1LC1RB : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB
  | StA, S1 => mk S0 DL StC
  | StB, S0 => mk S1 DR StC
  | StB, S1 => mk S0 DR StD
  | StC, S0 => mk S1 DL StA
  | StC, S1 => mk S0 DL StB
  | StD, S0 => mk S1 DL StC
  | StD, S1 => mk S1 DR StB
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_0RB0LC_1RC0RD_1LA0LB_1LC1RB : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_0RB0LC_1RC0RD_1LA0LB_1LC1RB pins_0RB0LC_1RC0RD_1LA0LB_1LC1RB).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_0RB0LC_1RC0RD_1LA0LB_1LC1RB : Fam := mkFam 2 [[S1;S0];[S1;S1]] [] [[S1];[]] Binary 1 [mkFill 1 [] 0 [1] 1;mkFill 1 [] 0 [] 0] StA S0 false [].
Local Notation FAM := fam_0RB0LC_1RC0RD_1LA0LB_1LC1RB.

(** ** The ladder, as DATA

    8 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_0RB0LC_1RC0RD_1LA0LB_1LC1RB : list (LRule * list rstep) :=
  [(mkLRule (mkC StA (mkS [S0;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StA (mkS [] [] 0 0 []) S1 (mkS [S1;S0] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StB (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [] 0 0 [])) (mkC StB (mkS [S1;S0] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [] 0 0 [])) (mkC StD (mkS [S0;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1;S1;S1;S1] [] 0 0 [])) (mkC StD (mkS [S0;S1;S0;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 4, [RB (SWin 4)]);
   (mkLRule (mkC StC (mkS [S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 [])) (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S0;S1] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StA (mkS [S1;S0] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StA (mkS [] [] 0 0 []) S1 (mkS [S1;S0] [] 0 0 [])) 0 4, [RB (SWin 4)]);
   (mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [] 0 0 [])) (mkC StD (mkS [S0;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StB (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [] 0 0 [])) (mkC StB (mkS [S1;S0] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 2, [RB (SWin 2)])].
Local Notation lad := lad_0RB0LC_1RC0RD_1LA0LB_1LC1RB.

Definition rules_0RB0LC_1RC0RD_1LA0LB_1LC1RB : list LRule := map fst lad.
Local Notation rules := rules_0RB0LC_1RC0RD_1LA0LB_1LC1RB.

Lemma ladder_ok_0RB0LC_1RC0RD_1LA0LB_1LC1RB : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_0RB0LC_1RC0RD_1LA0LB_1LC1RB : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_0RB0LC_1RC0RD_1LA0LB_1LC1RB. Qed.

