(** ** What this board establishes

    53 of 53 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 53 of them
    collapse to 3 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 0 stride 1, the fill class at threshold 1
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)
Definition iarm0_0_0RB0LC_1RC0RD_1LA0LB_1LC1RB : LRule :=
  mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [] [S1;S1] 1 0 [S1;S0]))
          (mkC StA (mkS [] [] 0 0 []) S0 (mkS [] [S1;S0] 1 0 [S1;S1])) 4 4.
Definition ch_iarm0_0_0RB0LC_1RC0RD_1LA0LB_1LC1RB : list rstep := [RB (SRotR 1);RB (SWin 1);RB (SCycR 2);RB (SWin 2);RB (SCycL 2 0);RB (SWin 1);RB (SUnrotR 1)].
Lemma ok_iarm0_0_0RB0LC_1RC0RD_1LA0LB_1LC1RB :
  check_arm tm true false rules iarm0_0_0RB0LC_1RC0RD_1LA0LB_1LC1RB
            ch_iarm0_0_0RB0LC_1RC0RD_1LA0LB_1LC1RB = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm_0RB0LC_1RC0RD_1LA0LB_1LC1RB (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_0RB0LC_1RC0RD_1LA0LB_1LC1RB
  | _, _ => iarm0_0_0RB0LC_1RC0RD_1LA0LB_1LC1RB   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_0RB0LC_1RC0RD_1LA0LB_1LC1RB : LRule :=
  mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S1] [S1;S1] 1 0 [S1]))
          (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S0] [S1;S0] 1 0 [S1;S1])) 4 8.
Definition ch_farm1_0_0RB0LC_1RC0RD_1LA0LB_1LC1RB : list rstep := [RB (SWin 2);RB (SCycR 2);RB (SWin 1);RB (SWinR 3);RB (SCycL 2 0);RB (SWin 2)].
Lemma ok_farm1_0_0RB0LC_1RC0RD_1LA0LB_1LC1RB :
  check_arm tm true true rules farm1_0_0RB0LC_1RC0RD_1LA0LB_1LC1RB
            ch_farm1_0_0RB0LC_1RC0RD_1LA0LB_1LC1RB = true.
Proof. vm_compute. reflexivity. Qed.

