Lemma fm12_0RB0LC_1RC0RD_1LA0LB_1LC1RB : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 2 ->
  fm1_0RB0LC_1RC0RD_1LA0LB_1LC1RB r ph + fm2_0RB0LC_1RC0RD_1LA0LB_1LC1RB r ph
  + (length (f_pre (fam_fill FAM ph)) + length (f_suf (fam_fill FAM ph)))
