  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S0] [] 0 0 []))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S1;S0] [] 0 0 [])) 0 2.
