Lemma farm_rhs_0RB0RC_1LC1RD_0LD1RA_1RC1LD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  lr_rhs (farm_0RB0RC_1LC1RD_0LD1RA_1RC1LD r ph)
    = cls_conf FAM (run_side FAM (f_mid (fam_fill FAM ph)) (fm1_0RB0RC_1LC1RD_0LD1RA_1RC1LD r ph)
                      (astride 1 1 r) (fm2_0RB0RC_1LC1RD_0LD1RA_1RC1LD r ph)
                      (f_to (fam_fill FAM ph))
