  mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [] [S1;S0;S0] 1 0 [S1;S1;S0]))
          (mkC StA (mkS [] [] 0 0 []) S0 (mkS [] [S1;S1;S1] 1 0 [S1;S0;S0])) 6 4.
