Proof. vm_compute. reflexivity. Qed.

Definition iarm_0RB1LA_1LA1RC_1RD0LA_1RB1LB (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_0RB1LA_1LA1RC_1RD0LA_1RB1LB
  | 1, 0 => iarm1_0_0RB1LA_1LA1RC_1RD0LA_1RB1LB
  | 2, 0 => iarm2_0_0RB1LA_1LA1RC_1RD0LA_1RB1LB
  | _, _ => iarm0_0_0RB1LA_1LA1RC_1RD0LA_1RB1LB   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_0RB1LA_1LA1RC_1RD0LA_1RB1LB : LRule :=
  mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S0;S0] [S1;S0;S0] 1 0 []))
          (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S1])) 6 8.
Definition ch_farm1_0_0RB1LA_1LA1RC_1RD0LA_1RB1LB : list rstep := [RB (SWin 3);RB (SCycR 3);RB (SWinR 2);RB (SCycL 3 0);RB (SWin 3)].
