Definition iarm_0RB1LA_1LC1RD_1RB1LB_1RC0LA (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_0RB1LA_1LC1RD_1RB1LB_1RC0LA
  | 1, 0 => iarm1_0_0RB1LA_1LC1RD_1RB1LB_1RC0LA
  | 2, 0 => iarm2_0_0RB1LA_1LC1RD_1RB1LB_1RC0LA
  | _, _ => iarm0_0_0RB1LA_1LC1RD_1RB1LB_1RC0LA   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

