Lemma bootl_0RB1LA_1LC1RD_1RB1LB_1RC0LA :
  stepn tm 39 InitES = Some (lift (fam_cfg FAM ([2;2], 0, 0))).
Proof.
  assert (H : match csteps tm 39 c0 with
              | Some c => ceqb c (fam_cfg FAM ([2;2], 0, 0))
