(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_0RB1LA_1RC0LA_1LA1RD_1RB0LA : NeverQuasiHaltsTr tm_0RB1LA_1RC0LA_1LA1RD_1RB0LA.
Proof.
  eapply (boardphL_neverqhtr tm_0RB1LA_1RC0LA_1LA1RD_1RB0LA pins_0RB1LA_1RC0LA_1LA1RD_1RB0LA FAM 1
    iarm_0RB1LA_1RC0LA_1LA1RD_1RB0LA 1 1 farm_0RB1LA_1RC0LA_1LA1RD_1RB0LA 1 1 fm1_0RB1LA_1RC0LA_1LA1RD_1RB0LA fm2_0RB1LA_1RC0LA_1LA1RD_1RB0LA padl_0RB1LA_1RC0LA_1LA1RD_1RB0LA padr_0RB1LA_1RC0LA_1LA1RD_1RB0LA
    0 vis_0RB1LA_1RC0LA_1LA1RD_1RB0LA [2] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_0RB1LA_1RC0LA_1LA1RD_1RB0LA.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - lia.
  - exact iarm_sound_0RB1LA_1RC0LA_1LA1RD_1RB0LA.
  - exact iarm_lhs_0RB1LA_1RC0LA_1LA1RD_1RB0LA.
  - exact iarm_rhs_0RB1LA_1RC0LA_1LA1RD_1RB0LA.
  - exact iarm_cb_0RB1LA_1RC0LA_1LA1RD_1RB0LA.
  - lia.
  - lia.
  - exact farm_sound_0RB1LA_1RC0LA_1LA1RD_1RB0LA.
  - exact farm_lhs_0RB1LA_1RC0LA_1LA1RD_1RB0LA.
  - exact farm_rhs_0RB1LA_1RC0LA_1LA1RD_1RB0LA.
  - exact farm_cb_0RB1LA_1RC0LA_1LA1RD_1RB0LA.
  - exact vis_ok_0RB1LA_1RC0LA_1LA1RD_1RB0LA.
  - exact bootl_0RB1LA_1RC0LA_1LA1RD_1RB0LA.
Qed.

